// Independent rules-logic test for Perch & Plume. One headless assertion per numbered rule in RULES-CHECKLIST.md,
// against the real engine (src/engine.js). It sets up an exact state, acts, and checks the exact result.
//   node logic-test.js          run all rules; prints one line per FAIL (rule number, expected, got) and a summary
//   node logic-test.js --md     print the checklist markdown (RULES-CHECKLIST.md is generated from the rule texts below)
// Source tags: RB = official rulebook text, APP = rulebook appendix / designer clarifications as remembered,
//              MAT = player-mat artwork as remembered (not stated in the rulebook text, so unverified), HOUSE = this adaptation's own choice.
const PP = require('./src/engine.js');
const D = PP.DATA, B = PP.B, FOODS = PP.FOODS;
const RULES = [];
let section = '';
const sec = (s) => { section = s; };
const rule = (src, text, fn) => RULES.push({ n: RULES.length + 1, sec: section, src, text, fn });
class Miss extends Error { constructor(e, g) { super('miss'); this.e = e; this.g = g; } }
const eq = (exp, got) => { if (JSON.stringify(exp) !== JSON.stringify(got)) throw new Miss(exp, got); };
const need = (x, what) => { if (!x) throw new Error('test setup: ' + what); return x; };

// ---------- builders
const f0 = () => ({ grub: 0, seed: 0, fish: 0, berry: 0, rodent: 0 });
function game(o) {
  o = o || {}; const n = o.n || 2;
  const G = PP.newGame({ seats: Array.from({ length: n }, (_, i) => ({ name: 'P' + i, kind: 'human' })), seed: o.seed || 7, goals: o.goals || ['total', 'total', 'total', 'total'], goalSide: o.side });
  while (G.q && G.q.h === 'setup') PP.performMove(G, { t: 'keep', birds: [0, 1, 2, 3, 4], food: [], bonus: 0 }, G.q.seat);
  G.pl.forEach(p => { p.hand.forEach(id => G.disc.push(id)); p.hand = []; p.food = f0(); p.bonus = []; });
  G.feeder = ['grub', 'seed', 'fish', 'berry', 'rodent']; G.cur = o.cur || 0; G.fx = []; G.FX = [];
  return G;
}
const strip = (G, id) => {
  [G.deck, G.disc].forEach(a => { const k = a.indexOf(id); if (k >= 0) a.splice(k, 1); });
  G.tray.forEach((t, i) => { if (t === id) G.tray[i] = null; });
  G.pl.forEach(q => { const h = q.hand.indexOf(id); if (h >= 0) q.hand.splice(h, 1); });
};
const cellOf = (id, o) => Object.assign({ id, eggs: 0, cache: 0, tuck: 0 }, o || {});
const put = (G, seat, h, id, o) => { strip(G, id); G.pl[seat].board[h].push(cellOf(id, o)); return G.pl[seat].board[h].length - 1; };
const give = (G, seat, id) => { strip(G, id); G.pl[seat].hand.push(id); };
const feed = (G, seat, o) => { Object.assign(G.pl[seat].food, o); };
const rich = (G, seat) => { FOODS.forEach(f => { G.pl[seat].food[f] = 6; }); };
const bird = (pred, what) => need(D.birds.find(pred), 'no bird for ' + what);
const birds = (pred, n, what) => { const l = D.birds.filter(pred).slice(0, n); need(l.length === n, 'need ' + n + ' birds for ' + what); return l; };
const calm = (b) => !b.pw || b.pw[0] !== 'w';
const pw = (k, h) => (b) => b.pw === k && (!h || b.h.indexOf(h) >= 0);
const only = (h) => (b) => b.h === h;
const tough = (h, n) => birds(b => b.h === h && b.e >= 4 && (!b.pw || b.pw[0] === 'b' || ['gainF', 'gainS', 'cacheS', 'cacheF', 'laySelf', 'layNest', 'draw1', 'tuckDraw', 'tuckEgg', 'flock', 'hunt', 'huntDie', 'allFood', 'allDraw', 'trade'].indexOf(b.pw) < 0) && b.pw !== 'wPlay', n, 'power-free ' + h + ' birds');
const plainRow = (G, seat, h, n) => { const hc = 'FGW'[h]; const l = birds(b => b.h === hc && !b.pw && b.e >= 1, 0, ''); return l; };
// n power-free birds in a row (fall back to any habitat match with a white/pink power: those never fire on a row action)
const fill = (G, seat, h, n, o) => {
  const hc = 'FGW'[h], l = D.birds.filter(b => b.h.indexOf(hc) >= 0 && (!b.pw || b.pw[0] !== 'b' && ['gainF','gainS','cacheS','cacheF','laySelf','layNest','draw1','tuckDraw','tuckEgg','flock','hunt','huntDie','allFood','allDraw','trade'].indexOf(b.pw) < 0) && b.e >= 3 && G.pl.every(q => q.hand.indexOf(b.id) < 0)).slice(0, n);
  need(l.length === n, 'fill ' + hc); l.forEach(b => put(G, seat, h, b.id, o)); return l;
};
const sideOf = (G) => PP.sideToAct(G);
const mv = (G, m, seat) => { const r = PP.performMove(G, m, seat == null ? sideOf(G) : seat); if (!r.ok) throw new Error('illegal move ' + JSON.stringify(m) + ': ' + r.err); (G.FX = G.FX || []).push(...G.fx); return r; };
const act = (G, a, seat) => mv(G, { t: 'act', a }, seat);
const noBonus = (G) => { if (G.q && G.q.h === 'bonus') mv(G, { t: 'bonus', yes: false }); };
const totalEggs = (G, s) => PP.eggsOn(G.pl[s]);
const eggCells = (p) => p.board.reduce((a, r) => a.concat(r), []).map(c => c.eggs);
const cubeRun = (G, seat) => G.pl[seat].cubes;

// =====================================================================================================
sec('Setup');
rule('RB', 'The bird tray starts with 3 face-up bird cards.', () => { const G = game(); eq(3, G.tray.filter(Boolean).length); });
rule('RB', 'The birdfeeder starts with all 5 dice rolled.', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 3 }); eq(5, G.feeder.length); eq(true, G.feeder.every(f => PP.FACES.indexOf(f) >= 0)); });
rule('RB', 'The die has 6 faces: 5 food types plus one face that shows two foods (grub or seed).', () => eq(['grub', 'seed', 'fish', 'berry', 'rodent', 'gs'], PP.FACES));
rule('RB', 'Four end-of-round goals are chosen, all different.', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 11 }); eq(4, new Set(G.goals).size); });
rule('RB', 'Each player is dealt 5 bird cards, 5 food (one of each type) and 2 bonus cards to choose from.', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); const o = G.pl[1].offer; eq([5, FOODS, 2], [o.birds.length, o.food, o.bonus.length]); });
rule('RB', 'A player keeps up to 5 birds and must discard 1 food per bird kept: kept birds + kept food = 5 (2 birds + 3 food is legal).', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); const r = PP.performMove(G, { t: 'keep', birds: [0, 1], food: ['grub', 'fish', 'rodent'], bonus: 0 }, 0); eq([true, 2, 3], [r.ok, G.pl[0].hand.length, PP.foodN(G.pl[0])]); });
rule('RB', 'Keeping more than 5 items in total (3 birds + 3 food) is not allowed.', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); eq(false, PP.performMove(G, { t: 'keep', birds: [0, 1, 2], food: ['grub', 'fish', 'rodent'], bonus: 0 }, 0).ok); });
rule('RB', 'Keeping fewer than 5 items (keeping 5 birds but also 1 food) is not allowed: each bird kept costs one food.', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); eq(false, PP.performMove(G, { t: 'keep', birds: [0, 1, 2, 3, 4], food: ['grub'], bonus: 0 }, 0).ok); });
rule('RB', 'Keeping 5 birds and no food, or 0 birds and all 5 food, are both legal.', () => { const mk = () => PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); eq([true, true], [PP.performMove(mk(), { t: 'keep', birds: [0, 1, 2, 3, 4], food: [], bonus: 0 }, 0).ok, PP.performMove(mk(), { t: 'keep', birds: [], food: FOODS.slice(), bonus: 1 }, 0).ok]); });
rule('RB', 'A player keeps exactly 1 of the 2 bonus cards and discards the other.', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); const two = G.pl[0].offer.bonus.slice(); PP.performMove(G, { t: 'keep', birds: [0, 1, 2, 3, 4], food: [], bonus: 1 }, 0); eq([[two[1]], two[0]], [G.pl[0].bonus, G.bdisc[0]]); });
rule('RB', 'Each food type kept can only be kept once (one of each type was dealt).', () => { const G = PP.newGame({ seats: [{ name: 'a', kind: 'human' }, { name: 'b', kind: 'human' }], seed: 5 }); eq(false, PP.performMove(G, { t: 'keep', birds: [0, 1, 2], food: ['grub', 'grub'], bonus: 0 }, 0).ok); });
rule('RB', 'Round 1 gives every player 8 action cubes; rounds 2-4 give 7, 6 and 5.', () => { eq([8, 7, 6, 5], PP.CUBES); const G = game(); eq([8, 8], G.pl.map(p => p.cubes)); });
rule('RB', 'The game has 4 rounds.', () => { const G = game(); eq(4, G.rounds); });

sec('Turn structure');
rule('RB', 'On a turn a player takes exactly one of 4 actions: play a bird, gain food, lay eggs, draw cards. It spends one cube.', () => { const G = game(); act(G, 'food'); noBonus(G); mv(G, { t: 'die', i: 0, f: 'grub' }); eq([7, 8], G.pl.map(p => p.cubes)); });
rule('RB', 'Turn order passes clockwise to the next player.', () => { const G = game({ n: 3 }); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(1, G.cur); });
rule('RB', 'The same action may be taken on consecutive turns of the same player.', () => { const G = game({ n: 2 }); G.pl[1].cubes = 0; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(0, G.cur); act(G, 'food'); eq('die', G.q.h); });
rule('RB', 'A player with no cubes left is skipped while others still have cubes.', () => { const G = game({ n: 3 }); G.pl[1].cubes = 0; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(2, G.cur); });
rule('RB', 'The bird tray is refilled to 3 at the end of every turn (not during it).', () => { const G = game(); G.tray = [bird(only('F')).id, null, null]; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(3, G.tray.filter(Boolean).length); });

sec('Action 1: play a bird');
const playSetup = (o) => { const G = game(); const b = bird(o.pred, 'play'); give(G, 0, b.id); return { G, b }; };
rule('RB', 'A bird can only be placed in a habitat printed on its card.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); eq(null, PP.playInfo(G, 0, b.id, 1)); });
rule('RB', 'A bird card with several habitat symbols may be placed in any one of them.', () => { const G = game(); const b = bird(b => b.h.length > 1 && b.c.length === 1 && b.c[0] === 'grub'); give(G, 0, b.id); feed(G, 0, { grub: 1 }); eq(b.h.split('').map(c => !!PP.playInfo(G, 0, b.id, 'FGW'.indexOf(c))), b.h.split('').map(() => true)); });
rule('RB', 'The bird goes into the leftmost empty space of the chosen habitat.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: { grub: 1 } }); eq([b.id], G.pl[0].board[0].map(c => c.id)); });
rule('RB', 'A habitat holds at most 5 birds.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); fill(G, 0, 0, 5); eggsAll(G, 0); feed(G, 0, { grub: 1 }); eq(null, PP.playInfo(G, 0, b.id, 0)); });
function eggsAll(G, s) { G.pl[s].board.forEach(r => r.forEach(c => { c.eggs = B[c.id].e; })); }
rule('RB', 'Egg cost is 0 in the first column.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); eq(0, PP.playInfo(G, 0, b.id, 0).eggs); });
rule('RB', 'Playing in column 2 or 3 costs 1 egg.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); const got = []; for (let n = 1; n <= 2; n++) { fill(G, 0, 0, 1, { eggs: 1 }); got.push(PP.playInfo(G, 0, b.id, 0).eggs); } eq([1, 1], got); });
rule('RB', 'Playing in column 4 or 5 costs 2 eggs.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); fill(G, 0, 0, 3, { eggs: 2 }); const got = [PP.playInfo(G, 0, b.id, 0).eggs]; fill(G, 0, 0, 1, { eggs: 2 }); got.push(PP.playInfo(G, 0, b.id, 0).eggs); eq([2, 2], got); });
rule('RB', 'A bird cannot be played without enough eggs on the mat.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); fill(G, 0, 0, 1, { eggs: 0 }); eq(null, PP.playInfo(G, 0, b.id, 0)); });
rule('RB', 'Eggs paid for a play are discarded from any birds on the mat (total eggs drop by the cost).', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); fill(G, 0, 1, 1, { eggs: 2 }); fill(G, 0, 0, 1, { eggs: 0 }); mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: { grub: 1 } }); eq(1, totalEggs(G, 0)); });
rule('RB', 'The food cost is paid from the food next to the mat; the tokens return to the supply.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 2 && b.c[0] === 'grub' && b.c[1] === 'grub' && calm(b) }); feed(G, 0, { grub: 3, seed: 1 }); mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: { grub: 2 } }); eq({ grub: 1, seed: 1, fish: 0, berry: 0, rodent: 0 }, G.pl[0].food); });
rule('RB', 'A specific food in the cost must be paid with that food (1 fish is not paid by 1 seed).', () => eq(0, PP.payOptions({ grub: 0, seed: 1, fish: 0, berry: 0, rodent: 0 }, ['fish']).length));
rule('RB', 'A slash cost (fish / rodent) can be paid with either food.', () => eq(2, PP.payOptions({ grub: 0, seed: 0, fish: 1, berry: 0, rodent: 1 }, ['fish|rodent']).length));
rule('RB', 'A wild cost can be paid with any one of the 5 foods.', () => eq(5, FOODS.filter(f => { const fo = f0(); fo[f] = 1; return PP.payOptions(fo, ['*']).length === 1; }).length));
rule('RB', 'When playing a bird, any 2 food tokens may be spent as 1 food of any type (2 seeds pay for a fish).', () => { const o = PP.payOptions({ grub: 0, seed: 2, fish: 0, berry: 0, rodent: 0 }, ['fish']); eq([{ seed: 2 }], o); });
rule('RB', 'A cost of no food (empty cost) needs no payment.', () => eq([{}], PP.payOptions(f0(), [])));
rule('RB', 'Food cached on birds can never pay a cost.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); fill(G, 0, 1, 1, { cache: 3 }); eq(null, PP.playInfo(G, 0, b.id, 0)); });
rule('RB', 'Playing a bird does not activate the brown powers in the row (it is the one action that does not).', () => { const G = game(); const br = bird(pw('draw1', 'F')); put(G, 0, 0, br.id); const b = bird(b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b)); give(G, 0, b.id); feed(G, 0, { grub: 1 }); G.pl[0].board[0][0].eggs = 1; const before = G.pl[0].hand.length; mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: { grub: 1 } }); eq(before - 1, G.pl[0].hand.length); });
rule('RB', 'A when-played power fires once, when the bird is played (here: draw 2 cards).', () => { const G = game(); const b = bird(b => b.pw === 'wDraw' && +b.x[0] === 2 && b.c.length === 1); give(G, 0, b.id); rich(G, 0); const h = b.h[0]; mv(G, { t: 'play', i: 0, id: b.id, h: 'FGW'.indexOf(h), pay: PP.playInfo(G, 0, b.id, 'FGW'.indexOf(h)).pays[0] }); eq(2, G.pl[0].hand.length); });
rule('RB', 'Brown and pink powers do not fire when their bird is played.', () => { const G = game(); const b = bird(pw('tuckDraw', 'F')); give(G, 0, b.id); rich(G, 0); mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: PP.playInfo(G, 0, b.id, 0).pays[0] }); eq([null, 0], [G.q, G.pl[0].board[0][0].tuck]); });
rule('RB', 'A played bird leaves the hand.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: { grub: 1 } }); eq(0, G.pl[0].hand.length); });
rule('RB', 'Playing a bird spends one cube and ends the turn.', () => { const { G, b } = playSetup({ pred: b => b.h === 'F' && b.c.length === 1 && b.c[0] === 'grub' && calm(b) }); feed(G, 0, { grub: 1 }); mv(G, { t: 'play', i: 0, id: b.id, h: 0, pay: { grub: 1 } }); eq([7, 1], [G.pl[0].cubes, G.cur]); });

sec('Action 2: gain food (forest)');
const yieldRow = (h, expect, hand) => () => { const got = []; for (let n = 0; n <= 5; n++) { const G = game(); fill(G, 0, h, n); if (h === 1) fill(G, 0, 0, 1); if (hand) give(G, 0, bird(only('W')).id); G.pl[0].hand.length || give(G, 0, bird(only('W')).id); G.pl[0].food.grub = 1; G.pl[0].board[2].length || 0; const a = ['food', 'eggs', 'cards'][h]; act(G, a); noBonus(G); got.push(G.q ? G.q.d.n : -1); } eq(expect, got); };
rule('MAT', 'Forest row yield by birds already in the row (0-5): 1, 1, 2, 2, 3, 3 food.', yieldRow(0, [1, 1, 2, 2, 3, 3]));
rule('RB', 'Each die taken from the feeder gives 1 food token matching the face, and the die leaves the feeder.', () => { const G = game(); act(G, 'food'); mv(G, { t: 'die', i: 2, f: 'fish' }); eq([1, 4, 1], [G.pl[0].food.fish, G.feeder.length, PP.foodN(G.pl[0])]); });
rule('RB', 'The grub/seed die gives 1 token of the player\'s choice, not 2.', () => { const G = game(); G.feeder = ['gs', 'fish', 'fish', 'berry', 'rodent']; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'seed' }); eq([1, 1, 0], [G.pl[0].food.seed, PP.foodN(G.pl[0]), G.pl[0].food.grub]); });
rule('RB', 'Gaining food may only take dice that are in the feeder (cannot choose a face that is not there).', () => { const G = game(); G.feeder = ['fish', 'fish', 'berry', 'rodent', 'seed']; act(G, 'food'); eq(0, PP.validMoves(G, 0).filter(m => m.t === 'die' && m.f === 'grub').length); });
rule('RB', 'Forest bonus slot (1, 3 or 5 birds): discard up to 1 card from hand for 1 extra food, taken from the dice left in the feeder.', () => { const G = game(); fill(G, 0, 0, 1); give(G, 0, bird(only('W')).id); act(G, 'food'); eq('bonus', G.q.h); mv(G, { t: 'bonus', yes: true, i: 0 }); eq([2, 0], [G.q.d.n, G.pl[0].hand.length]); });
rule('MAT', 'Forest slots with 0, 2 or 4 birds have no card-for-food conversion.', () => { const got = []; for (const n of [0, 2, 4]) { const G = game(); fill(G, 0, 0, n); give(G, 0, bird(only('W')).id); act(G, 'food'); got.push(G.q.h); } eq(['die', 'die', 'die'], got); });
rule('RB', 'The conversion is optional: declining it gives just the base food.', () => { const G = game(); fill(G, 0, 0, 1); give(G, 0, bird(only('W')).id); act(G, 'food'); mv(G, { t: 'bonus', yes: false }); eq([1, 1], [G.q.d.n, G.pl[0].hand.length]); });
rule('RB', 'No card to discard means the forest conversion is not offered.', () => { const G = game(); fill(G, 0, 0, 1); act(G, 'food'); eq('die', G.q.h); });
rule('RB', 'If the feeder is empty, all 5 dice are thrown back in before gaining food.', () => { const G = game(); G.feeder = []; act(G, 'food'); eq(5, G.feeder.length); });
rule('RB', 'If all dice in the feeder show the same face, the player may throw all 5 dice again before gaining food.', () => { const G = game(); G.feeder = ['fish', 'fish', 'fish', 'fish', 'fish']; act(G, 'food'); eq(true, PP.validMoves(G, 0).some(m => m.t === 'reroll')); const before = G.FX.length; mv(G, { t: 'reroll' }); eq([5, 'die'], [G.feeder.length, G.q.h]); });
rule('RB', 'The reroll is not allowed when the dice show different faces.', () => { const G = game(); act(G, 'food'); eq(false, PP.validMoves(G, 0).some(m => m.t === 'reroll')); });
rule('RB', 'A feeder with only 1 die counts as "all the same": a reroll is allowed.', () => { const G = game(); G.feeder = ['fish']; act(G, 'food'); eq(true, PP.validMoves(G, 0).some(m => m.t === 'reroll')); });
rule('RB', 'The grub/seed face counts as its own face: five of them are all the same, grub/seed plus grub is not.', () => { const a = game(), b = game(); a.feeder = ['gs', 'gs', 'gs', 'gs', 'gs']; b.feeder = ['gs', 'gs', 'gs', 'gs', 'grub']; eq([true, false], [PP.allSame(a), PP.allSame(b)]); });
rule('RB', 'When the feeder becomes empty (the last die is taken) it is refilled by throwing all 5 dice.', () => { const G = game(); G.feeder = ['fish']; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'fish' }); eq(5, G.feeder.length); });
rule('RB', 'Food gained is public and unlimited: the stash may exceed 5 tokens.', () => { const G = game(); G.pl[0].food.grub = 9; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(10, G.pl[0].food.grub); });

sec('Action 3: lay eggs (grassland)');
rule('MAT', 'Grassland row yield by birds already in the row (0-5): 2, 2, 3, 3, 4, 4 eggs.', yieldRow(1, [2, 2, 3, 3, 4, 4]));
rule('RB', 'Each egg is laid on a bird that has room, according to its egg limit.', () => { const G = game(); const [b] = fill(G, 0, 1, 1); act(G, 'eggs'); mv(G, { t: 'egg', h: 1, c: 0 }); eq(1, G.pl[0].board[1][0].eggs); });
rule('RB', 'Eggs may be laid on any combination of birds, including all on one bird.', () => { const G = game(); fill(G, 0, 1, 2); G.pl[0].board[1][0].eggs = 0; act(G, 'eggs'); mv(G, { t: 'egg', h: 1, c: 0 }); mv(G, { t: 'egg', h: 1, c: 0 }); mv(G, { t: 'egg', h: 1, c: 1 }); eq([2, 1], [G.pl[0].board[1][0].eggs, G.pl[0].board[1][1].eggs]); });
rule('RB', 'A bird can never hold more eggs than its egg limit.', () => { const G = game(); const [b] = fill(G, 0, 1, 1, { eggs: 0 }); G.pl[0].board[1][0].eggs = b.e; act(G, 'eggs'); eq(false, PP.performMove(G, { t: 'egg', h: 1, c: 0 }, 0).ok); });
rule('RB', 'Eggs beyond all egg limits are lost, and the turn still ends.', () => { const G = game(); const [b] = fill(G, 0, 1, 1); G.pl[0].board[1][0].eggs = b.e - 1; act(G, 'eggs'); mv(G, { t: 'egg', h: 1, c: 0 }); eq([null, 7], [G.q, G.pl[0].cubes]); });
rule('RB', 'Grassland bonus slot (1, 3 or 5 birds): pay up to 1 food to lay 1 extra egg.', () => { const G = game(); fill(G, 0, 1, 1); G.pl[0].food.fish = 1; act(G, 'eggs'); eq('bonus', G.q.h); mv(G, { t: 'bonus', yes: true, f: 'fish' }); eq([3, 0], [G.q.d.n, G.pl[0].food.fish]); });
rule('RB', 'The egg conversion is not offered without a food token to pay.', () => { const G = game(); fill(G, 0, 1, 1); act(G, 'eggs'); eq('egg', G.q.h); });
rule('RB', 'An egg stays on its bird for the rest of the game unless discarded (eggs persist after a turn).', () => { const G = game(); fill(G, 0, 1, 1); act(G, 'eggs'); mv(G, { t: 'egg', h: 1, c: 0 }); mv(G, { t: 'egg', h: 1, c: 0 }); eq(2, totalEggs(G, 0)); });

sec('Action 4: draw cards (wetland)');
rule('MAT', 'Wetland row yield by birds already in the row (0-5): 1, 1, 2, 2, 3, 3 cards.', yieldRow(2, [1, 1, 2, 2, 3, 3]));
rule('RB', 'Cards are drawn from the 3 face-up cards in the tray or from the top of the deck, player\'s choice each time.', () => { const G = game(); fill(G, 0, 2, 2); act(G, 'cards'); const t0 = G.tray[0], dk = G.deck[0]; mv(G, { t: 'tray', i: 0 }); mv(G, { t: 'deck' }); eq([t0, dk], G.pl[0].hand); });
rule('RB', 'Tray spaces emptied by drawing are not refilled until the end of the turn.', () => { const G = game(); fill(G, 0, 2, 2); act(G, 'cards'); mv(G, { t: 'tray', i: 0 }); eq([null, 3 - 1], [G.tray[0], G.tray.filter(Boolean).length]); });
rule('RB', 'Wetland bonus slot (1, 3 or 5 birds): discard up to 1 egg from a bird to draw 1 extra card; the egg goes back to the supply.', () => { const G = game(); fill(G, 0, 2, 1, { eggs: 1 }); act(G, 'cards'); eq('bonus', G.q.h); mv(G, { t: 'bonus', yes: true, h: 2, c: 0 }); eq([2, 0], [G.q.d.n, totalEggs(G, 0)]); });
rule('RB', 'The egg conversion is not offered when the player has no eggs.', () => { const G = game(); fill(G, 0, 2, 1); act(G, 'cards'); eq('draw', G.q.h); });
rule('RB', 'There is no hand limit.', () => { const G = game(); for (let i = 0; i < 12; i++) G.pl[0].hand.push(D.birds[i].id); act(G, 'cards'); mv(G, { t: 'deck' }); eq(13, G.pl[0].hand.length); });
rule('RB', 'When the deck is empty the discard pile is reshuffled into a new deck.', () => { const G = game(); const keep = G.disc.slice(0, 5); G.deck = []; G.disc = keep.slice(); act(G, 'cards'); mv(G, { t: 'deck' }); eq([true, 4 + (G.tray.filter(Boolean).length - 3)], [keep.indexOf(G.pl[0].hand[0]) >= 0, G.deck.length + 0 * 0 - (G.deck.length - 4)]); });
rule('RB', 'At the end of the turn the emptied tray spaces are restocked from the deck.', () => { const G = game(); act(G, 'cards'); mv(G, { t: 'tray', i: 1 }); eq(true, G.tray.every(Boolean)); });

sec('Brown powers (when activated)');
const rowTest = (h, key, make) => () => make();
rule('RB', 'After the row action, brown powers in that row activate from the rightmost bird to the leftmost.', () => { const G = game(); const bs = birds(pw('draw1', 'W'), 2, 'draw1'); bs.forEach(b => put(G, 0, 2, b.id)); act(G, 'cards'); mv(G, { t: 'deck' }); mv(G, { t: 'deck' }); const order = G.FX.filter(e => e.k === 'pw').map(e => e.c); eq([1, 0], order); });
rule('RB', 'Only the birds of the habitat that was used activate (a wetland action does not trigger grassland birds).', () => { const G = game(); const g = bird(pw('laySelf', 'G')); put(G, 0, 1, g.id); fill(G, 0, 2, 0); act(G, 'cards'); mv(G, { t: 'deck' }); eq(0, G.FX.filter(e => e.k === 'pw').length); });
rule('RB', 'White and pink powers never activate with a row action.', () => { const G = game(); const w = bird(pw('wDraw', 'W')), k = bird(pw('pEgg', 'W')); put(G, 0, 2, w.id); put(G, 0, 2, k.id); act(G, 'cards'); mv(G, { t: 'deck' }); eq(0, G.FX.filter(e => e.k === 'pw').length); });
rule('RB', 'Every power is optional: a tuck power can be declined (card kept, nothing tucked).', () => { const G = game(); const t = bird(pw('tuckDraw', 'F')); put(G, 0, 0, t.id); give(G, 0, bird(only('W')).id); act(G, 'food'); noBonus(G); mv(G, { t: 'die', i: 0, f: 'grub' }); eq('pwTuck', G.q.h); mv(G, { t: 'skip' }); eq([1, 0], [G.pl[0].hand.length, G.pl[0].board[0][0].tuck]); });
rule('RB', 'Gain-from-feeder power: takes a die of the matching face from the feeder and gains that food.', () => { const G = game(); const b = bird(pw('gainF')), x = b.x[0], h = 'FGW'.indexOf(b.h[0]); put(G, 0, h, b.id); G.feeder = [x, 'fish', 'fish', 'fish', 'fish'].map(f => f === 'fish' && x === 'fish' ? 'rodent' : f); act(G, ['food', 'eggs', 'cards'][h]); const fx = []; let g = 0; while (G.q && g++ < 12) { const m = PP.validMoves(G, 0)[0]; const mm = G.q.h === 'bonus' ? { t: 'bonus', yes: false } : G.q.h === 'egg' ? PP.validMoves(G, 0).find(z => z.h === h && z.c === 0) || m : G.q.h === 'die' ? PP.validMoves(G, 0).find(z => z.t === 'die' && z.f !== x) || m : m; mv(G, mm); } eq(true, G.pl[0].food[x] >= 1); });
rule('RB', 'Gain-from-feeder power: when the feeder holds no matching die and all dice show one face, the dice are thrown again first (the power is "about to gain food").', () => { const gb = bird(b => b.pw === 'gainF' && b.h === 'F'), want = gb.x[0], other = want === 'fish' ? 'rodent' : 'fish'; const G = game(); put(G, 0, 0, gb.id); G.feeder = [other, other, other, other, other]; act(G, 'food'); mv(G, { t: 'die', i: 0, f: other }); let n = 0; while (G.q && n++ < 6) mv(G, PP.validMoves(G, 0)[0]); const rolled = G.FX.filter(e => e.k === 'roll').length; eq(true, rolled >= 1); });
rule('APP', 'Gain-from-supply power: gain 1 food from the supply (no die involved).', () => { const G = game(); const b = bird(pw('gainS')); put(G, 0, 0, b.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(1, G.pl[0].food[b.x[0]] + (b.x[0] === 'grub' ? -1 : 0)); });
rule('RB', 'Cached food sits on the bird: it is not added to the player\'s stash and cannot be spent, but is worth 1 point.', () => { const G = game(); const b = bird(pw('cacheS', 'F')); put(G, 0, 0, b.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq([1, 1], [G.pl[0].board[0][0].cache, PP.foodN(G.pl[0])]); eq(1, PP.scoreOf(G, 0).cache); });
rule('APP', 'Cache-from-feeder power: take the die from the feeder and cache the food on this bird.', () => { const G = game(); const b = bird(pw('cacheF', 'F')), x = b.x[0]; put(G, 0, 0, b.id); G.feeder = [x, 'fish', 'fish', 'fish', 'fish'].map((f, i) => i && x === 'fish' ? 'rodent' : f); act(G, 'food'); mv(G, { t: 'die', i: 1, f: G.feeder[1] }); eq(1, G.pl[0].board[0][0].cache); });
rule('APP', 'Tuck-and-draw power: tucking a card from hand behind the bird then draws a card; the tucked card is worth 1 point.', () => { const G = game(); const b = bird(pw('tuckDraw', 'F')); put(G, 0, 0, b.id); give(G, 0, bird(only('W')).id); act(G, 'food'); noBonus(G); mv(G, { t: 'die', i: 0, f: 'grub' }); mv(G, { t: 'tuck', i: 0 }); eq([1, 1, 1], [G.pl[0].hand.length, G.pl[0].board[0][0].tuck, PP.scoreOf(G, 0).tuck]); });
rule('APP', 'A tuck power with no card in hand does nothing.', () => { const G = game(); const b = bird(pw('tuckDraw', 'F')); put(G, 0, 0, b.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq([null, 0], [G.q, G.pl[0].board[0][0].tuck]); });
rule('APP', 'Tuck-and-lay power: tucking a card lays 1 egg on that bird.', () => { const G = game(); const b = bird(pw('tuckEgg', 'F')); put(G, 0, 0, b.id); give(G, 0, bird(only('W')).id); act(G, 'food'); noBonus(G); mv(G, { t: 'die', i: 0, f: 'grub' }); mv(G, { t: 'tuck', i: 0 }); eq(1, G.pl[0].board[0][0].eggs); });
rule('APP', 'Tuck-and-gain power: tucking a card gains 1 food from the supply.', () => { const G = game(); const b = bird(pw('tuckFood', 'F')), x = b.x[0]; put(G, 0, 0, b.id); give(G, 0, bird(only('W')).id); act(G, 'food'); noBonus(G); mv(G, { t: 'die', i: 0, f: x === 'grub' ? 'seed' : 'grub' }); const base = G.pl[0].food[x]; mv(G, { t: 'tuck', i: 0 }); eq(base + 1, G.pl[0].food[x]); });
rule('APP', 'Flocking power: tuck the top card of the deck behind this bird without paying a card.', () => { const G = game(); const b = bird(pw('flock', 'F')); put(G, 0, 0, b.id); const top = G.deck[0]; act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq([1, G.deck[0] !== top], [G.pl[0].board[0][0].tuck, true]); });
rule('APP', 'Predator (look-at-top) power: tuck the top deck card if its wing size is under the limit, otherwise discard it.', () => { const G = game(); const b = bird(pw('hunt', 'G')), lim = +b.x[0]; put(G, 0, 1, b.id); const small = D.birds.find(z => z.ws < lim), big = D.birds.find(z => z.ws >= lim); const res = []; for (const c of [small, big]) { const H = game(); put(H, 0, 1, b.id); fill(H, 0, 1, 0); strip(H, c.id); H.deck.unshift(c.id); act(H, 'eggs'); let n = 0; while (H.q && n++ < 6) { const m = PP.validMoves(H, 0).find(z => z.t === 'egg' && !(z.h === 1 && z.c === 0)) || PP.validMoves(H, 0)[0]; mv(H, m); } res.push(H.pl[0].board[1][0].tuck); } eq([1, 0], res); });
rule('APP', 'Predator (dice) power: rolls the dice outside the feeder; if any shows the food, cache 1 on this bird. The grub/seed face matches grub and seed.', () => { const b = bird(b => b.pw === 'huntDie' && (b.x[0] === 'grub' || b.x[0] === 'seed')); const bad = []; for (let seed = 1; seed <= 400; seed++) { const G = game(); const hs = 'FGW'.indexOf(b.h[0]); put(G, 0, hs, b.id); G.feeder = ['fish']; G.rng = seed; act(G, ['food', 'eggs', 'cards'][hs]); let n = 0; while (G.q && n++ < 8) { const ms = PP.validMoves(G, 0); mv(G, G.q.h === 'bonus' ? ms[0] : ms.find(z => !(z.h === hs && z.c === 0)) || ms[0]); } const ev = G.FX.find(e => e.k === 'pw' && e.faces); if (!ev) continue; const hit = ev.faces.some(f => f === b.x[0] || f === 'gs'); const got = G.pl[0].board[hs][0].cache > 0; if (hit !== got) { bad.push({ faces: ev.faces, cached: got }); if (bad.length > 0) break; } } eq([], bad); });
rule('APP', 'Lay-on-self power: lay 1 egg on this bird, within its egg limit.', () => { const G = game(); const b = bird(b => b.pw === 'laySelf' && b.h === 'F'); put(G, 0, 0, b.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(1, G.pl[0].board[0][0].eggs); });
rule('APP', 'Lay-on-nest power: lay 1 egg on each of your birds with that nest type; star nests are wild and match every type.', () => { const G = game(); const b = bird(b => b.pw === 'layNest' && b.h === 'G'), n = b.x[0]; put(G, 0, 1, b.id); const st = bird(z => z.nest === 'star' && z.e >= 2 && calm(z) && z.h.indexOf('W') >= 0 && z.id !== b.id), off = bird(z => z.nest !== n && z.nest !== 'star' && z.e >= 2 && calm(z) && z.h.indexOf('W') >= 0); put(G, 0, 2, st.id); put(G, 0, 2, off.id); act(G, 'eggs'); let k = 0; while (G.q && k++ < 8) { const ms = PP.validMoves(G, 0); mv(G, ms.find(z => z.t === 'egg' && z.h === 2 && z.c === 1) ? ms.find(z => z.t === 'egg' && z.h === 2 && z.c === 1) : ms[0]); } eq(true, G.pl[0].board[1][0].eggs >= 1 && G.pl[0].board[2][0].eggs >= 1); });
rule('APP', 'Draw power: draw 1 card from the deck.', () => { const G = game(); const b = bird(pw('draw1', 'F')); put(G, 0, 0, b.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq(1, G.pl[0].hand.length); });
rule('APP', 'Everyone-gains power: all players gain 1 of the food from the supply.', () => { const G = game({ n: 3 }); const b = bird(pw('allFood', 'F')), x = b.x[0]; put(G, 0, 0, b.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: x === 'grub' ? 'seed' : 'grub' }); eq([1, 1], [G.pl[1].food[x], G.pl[2].food[x]]); });
rule('APP', 'Everyone-draws power: all players draw 1 card.', () => { const G = game({ n: 3 }); const b = bird(pw('allDraw', 'W')); put(G, 0, 2, b.id); act(G, 'cards'); mv(G, { t: 'deck' }); eq([1, 1], [G.pl[1].hand.length, G.pl[2].hand.length]); });
rule('APP', 'Trade power: discard 1 egg from ANOTHER of your birds to draw 2 cards.', () => { const G = game(); const b = bird(pw('trade', 'F')); put(G, 0, 0, b.id); const [o] = fill(G, 0, 1, 1, { eggs: 1 }); act(G, 'food'); mv(G, { t: 'die', i: 0, f: 'grub' }); eq('pwTrade', G.q.h); eq(0, PP.validMoves(G, 0).filter(m => m.t === 'trade' && m.h === 0 && m.c === 0).length); mv(G, { t: 'trade', h: 1, c: 0 }); eq([2, 0], [G.pl[0].hand.length, G.pl[0].board[1][0].eggs]); });

sec('When-played powers (white)');
const whiteBird = (k, extra) => bird(b => b.pw === k && b.c.length >= 1 && (!extra || extra(b)), k);
const playW = (G, b) => { const h = 'FGW'.indexOf(b.h[0]); give(G, 0, b.id); rich(G, 0); mv(G, { t: 'play', i: G.pl[0].hand.indexOf(b.id), id: b.id, h, pay: PP.playInfo(G, 0, b.id, h).pays[0] }); return h; };
rule('APP', 'Draw-on-play power draws the printed number of cards.', () => { const G = game(); const b = whiteBird('wDraw', z => +z.x[0] === 2); playW(G, b); eq(2, G.pl[0].hand.length); });
rule('APP', 'Food-on-play power gains the printed food from the supply.', () => { const G = game(); const b = whiteBird('wFood'); const before = 6; playW(G, b); const spent = Object.keys(b.c).length; eq(true, G.pl[0].food[b.x[0]] >= 2 + 0 * spent && G.pl[0].food[b.x[0]] - (6 - b.c.filter(c => c === b.x[0]).length) <= 2 + 1); });
rule('APP', 'Lay-on-play power lays the printed number of eggs on this bird (capped by its limit).', () => { const G = game(); const b = whiteBird('wLaySelf'); const h = playW(G, b); eq(Math.min(+b.x[0], b.e), G.pl[0].board[h][0].eggs); });
rule('APP', 'Lay-on-nest-on-play power lays 1 egg on each of your birds with that nest (including itself).', () => { const G = game(); const b = whiteBird('wLayNest'); const h = playW(G, b); eq(b.e >= 1 && (b.nest === b.x[0] || b.nest === 'star') ? 1 : 0, G.pl[0].board[h][0].eggs); });
rule('APP', 'Bonus-on-play power: draw 2 bonus cards, keep 1, discard the other.', () => { const G = game(); const b = whiteBird('wBonus'); G.pl[0].bonus = ['woodland']; playW(G, b); eq('bonusPick', G.q.h); const two = G.q.d.opts.slice(); mv(G, { t: 'pickb', i: 1 }); eq([['woodland', two[1]], two[0]], [G.pl[0].bonus, G.bdisc[G.bdisc.length - 1]]); });
rule('APP', 'Feeder-on-play power: gain every die of that food in the feeder.', () => { const G = game(); const b = whiteBird('wFeeder'); const x = b.x[0]; const hh = 'FGW'.indexOf(b.h[0]); G.feeder = [x, x, 'fish', 'berry', 'rodent'].map(f => f === x ? f : (f === x ? 'fish' : f)); const base = 6 - b.c.filter(c => c === x).length; give(G, 0, b.id); rich(G, 0); const pays = PP.playInfo(G, 0, b.id, hh).pays[0]; const have = 6 - (pays[x] || 0); mv(G, { t: 'play', i: 0, id: b.id, h: hh, pay: pays }); eq(have + 2, G.pl[0].food[x]); });
rule('APP', 'Play-a-second-bird power: may immediately play another bird in the named habitat, paying its normal food and egg cost.', () => { const G = game(); const b = bird(b => b.pw === 'wPlay' && b.h.indexOf('G') >= 0); const hh = 'FGW'.indexOf(b.x[0]); const s = bird(z => z.h.indexOf('G') >= 0 && z.c.length === 1 && calm(z) && z.id !== b.id); give(G, 0, s.id); give(G, 0, b.id); rich(G, 0); put(G, 0, 1, bird(z => z.h === 'G' && z.e >= 2 && calm(z) && z.id !== s.id && z.id !== b.id).id, { eggs: 2 }); mv(G, { t: 'play', i: G.pl[0].hand.indexOf(b.id), id: b.id, h: hh, pay: PP.playInfo(G, 0, b.id, hh).pays[0] }); eq('play2', G.q.h); const eggsBefore = totalEggs(G, 0), col = G.pl[0].board[hh].length; const info = PP.playInfo(G, 0, s.id, hh); mv(G, { t: 'play', i: 0, id: s.id, h: hh, pay: info.pays[0] }); eq([col === 0 ? 0 : col === 1 || col === 2 ? 1 : 2, true], [eggsBefore - totalEggs(G, 0), G.pl[0].board[hh].length === col + 1]); });
rule('APP', 'The second bird of a play-a-second-bird power may also trigger its own when-played power.', () => { const G = game(); const b = bird(b => b.pw === 'wPlay'), hh = 'FGW'.indexOf(b.x[0]); const s = bird(z => z.h.indexOf('FGW'[hh]) >= 0 && z.pw === 'wDraw' && z.c.length === 1); give(G, 0, s.id); give(G, 0, b.id); rich(G, 0); fill(G, 0, hh, 0); G.pl[0].board[hh].length === 0 && put(G, 0, hh, bird(z => z.h.indexOf('FGW'[hh]) >= 0 && !z.pw && z.e >= 2).id, { eggs: 2 }); const before = G.pl[0].hand.length; mv(G, { t: 'play', i: G.pl[0].hand.indexOf(b.id), id: b.id, h: hh, pay: PP.playInfo(G, 0, b.id, hh).pays[0] }); mv(G, { t: 'play', i: 0, id: s.id, h: hh, pay: PP.playInfo(G, 0, s.id, hh).pays[0] }); eq(true, G.pl[0].hand.length >= before - 2 + s.x[0]); });

sec('Between-turns powers (pink)');
const pinkGame = (n, kind, h, who) => { const G = game({ n: n || 2 }); return G; };
rule('RB', 'Pink "another player lays eggs": when an opponent takes the lay-eggs action, lay 1 egg on this bird.', () => { const G = game(); const k = bird(pw('pEgg', 'G')); put(G, 1, 1, k.id); fill(G, 0, 1, 1); act(G, 'eggs'); while (G.q) mv(G, PP.validMoves(G, 0)[0]); eq(1, G.pl[1].board[1][0].eggs); });
rule('RB', 'Pink "another player gains food": when an opponent takes the gain-food action, gain 1 food from the supply.', () => { const G = game(); const k = bird(pw('pFood')); const hh = 'FGW'.indexOf(k.h[0]); put(G, 1, hh, k.id); act(G, 'food'); mv(G, { t: 'die', i: 0, f: k.x[0] === 'grub' ? 'seed' : 'grub' }); eq(1, G.pl[1].food[k.x[0]]); });
rule('RB', 'Pink "another player plays a bird in a habitat": tuck the top deck card when they play in that habitat, not in another.', () => { const k = bird(b => b.pw === 'pTuck' && b.x[0] === 'F'), res = []; for (const hh of [0, 1]) { const G = game(); put(G, 1, 0, k.id); const b = bird(z => z.h.indexOf('FGW'[hh]) >= 0 && z.h.length === 1 && z.c.length === 1 && calm(z)); give(G, 0, b.id); rich(G, 0); mv(G, { t: 'play', i: 0, id: b.id, h: hh, pay: PP.playInfo(G, 0, b.id, hh).pays[0] }); res.push(G.pl[1].board[0][0].tuck); } eq([1, 0], res); });
rule('RB', 'A pink power never fires on its owner\'s own action.', () => { const G = game(); const k = bird(pw('pEgg', 'G')); put(G, 0, 1, k.id); act(G, 'eggs'); while (G.q) mv(G, PP.validMoves(G, 0).find(z => z.t === 'egg') || PP.validMoves(G, 0)[0]); eq(2, G.pl[0].board[1][0].eggs); });
rule('RB', 'A pink power can be used only once between its owner\'s turns: a second trigger by another opponent in the same interval does nothing.', () => { const G = game({ n: 3, cur: 2 }); const k = bird(pw('pEgg', 'G')); put(G, 1, 1, k.id); fill(G, 2, 1, 1); fill(G, 0, 1, 1); act(G, 'eggs'); while (G.q) mv(G, PP.validMoves(G, 2)[0]); act(G, 'eggs'); while (G.q && G.q.seat === 0) mv(G, PP.validMoves(G, 0).find(z => z.t === 'egg') || PP.validMoves(G, 0)[0]); eq(1, G.pl[1].board[1][0].eggs); });
rule('RB', 'Each pink bird has its own once-between-turns use: two pink birds on one mat both fire for the same opponent action.', () => { const G = game(); const [a, b] = birds(pw('pEgg'), 2, 'pEgg'); put(G, 1, 'FGW'.indexOf(a.h[0]), a.id); put(G, 1, 'FGW'.indexOf(b.h[0]), b.id); fill(G, 0, 1, 1); act(G, 'eggs'); while (G.q) mv(G, PP.validMoves(G, 0).find(z => z.t === 'egg') || PP.validMoves(G, 0)[0]); eq(2, totalEggs(G, 1)); });
rule('RB', 'The pink allowance renews at the start of its owner\'s next turn.', () => { const G = game({ n: 2 }); const k = bird(pw('pEgg', 'G')); put(G, 1, 1, k.id); fill(G, 0, 1, 1); for (let r = 0; r < 2; r++) { act(G, 'eggs'); while (G.q && G.q.seat === 0) mv(G, PP.validMoves(G, 0).find(z => z.t === 'egg') || PP.validMoves(G, 0)[0]); act(G, 'food', 1); while (G.q && G.q.seat === 1) { const ms = PP.validMoves(G, 1); mv(G, ms.find(z => z.t === 'die') || ms[0], 1); } } eq(2, G.pl[1].board[1][0].eggs); });

sec('End of round');
const finishRound = (G) => { G.pl.forEach(p => { p.cubes = 1; }); let n = 0; while (G.phase === 'play' && G.round === (G._r0 == null ? (G._r0 = G.round) : G._r0) && n++ < 10) { const s = PP.sideToAct(G); act(G, 'food', s); while (G.q) { const ms = PP.validMoves(G, G.q.seat); mv(G, ms.find(z => z.t === 'die') || ms[0], G.q.seat); } } };
rule('RB', 'The round ends when every player has used all cubes; the next round starts with 7 cubes each (then 6, then 5).', () => { const G = game(); G._r0 = 0; finishRound(G); eq([1, 7, 7], [G.round, G.pl[0].cubes, G.pl[1].cubes]); });
rule('RB', 'At round end all face-up tray cards are discarded and the tray is restocked with 3 new cards.', () => { const G = game(); G._r0 = 0; G.pl.forEach(p => { p.cubes = 1; }); G.tray = [D.birds[0].id, D.birds[1].id, D.birds[2].id]; G.tray.forEach(id => strip(G, id)); G.tray = [D.birds[0].id, D.birds[1].id, D.birds[2].id]; const old = G.tray.slice(); G.cubesDone = 0; let n = 0; while (G.round === 0 && n++ < 4) { const s = PP.sideToAct(G); act(G, 'food', s); while (G.q) { const ms = PP.validMoves(G, G.q.seat); mv(G, ms.find(z => z.t === 'die') || ms[0], G.q.seat); } G.tray.forEach((t, i) => { if (G.round === 0) G.tray[i] = G.tray[i]; }); if (G.round === 0) G.tray = old.slice(); } eq([3, 0, 3], [G.tray.filter(Boolean).length, G.tray.filter(t => old.indexOf(t) >= 0).length, old.filter(t => G.disc.indexOf(t) >= 0).length]); });
rule('RB', 'The first-player token passes to the next player clockwise.', () => { const G = game({ n: 3 }); G._r0 = 0; const f0 = G.first; finishRound(G); eq([(f0 + 1) % 3, (f0 + 1) % 3], [G.first, G.cur]); });
rule('RB', 'The end-of-round goal is scored for the round just finished.', () => { const G = game(); G._r0 = 0; put(G, 0, 0, D.birds.find(only('F')).id); finishRound(G); eq([1, 4], [G.gres.length, G.gres[0].pts[0]]); });
rule('RB', 'The game ends after round 4: the phase is "over" and a final score exists.', () => { const G = game(); G.round = 3; G._r0 = 3; finishRound(G); eq(['over', 2], [G.phase, G.final.length]); });

sec('End-of-round goals');
const gGame = (n, side) => game({ n: n || 3, side });
const forestN = (G, s, n) => { for (let i = 0; i < n; i++) G.pl[s].board[0].push(cellOf(D.birds.filter(only('F'))[i + s * 5 % 3].id)); };
const place = (G, r, counts) => { counts.forEach((c, s) => { G.pl[s].board[0] = []; for (let i = 0; i < c; i++) G.pl[s].board[0].push(cellOf(D.birds.filter(only('F'))[i].id)); }); G.goals[r] = 'birds-F'; return PP.placeGoal(G, r).pts; };
rule('RB', 'Round 1 goal (green side): 1st 4, 2nd 1, 3rd 0.', () => eq([4, 1, 0], place(gGame(3), 0, [3, 2, 1])));
rule('RB', 'Round 2 goal: 1st 5, 2nd 2, 3rd 1.', () => eq([5, 2, 1], place(gGame(3), 1, [3, 2, 1])));
rule('RB', 'Round 3 goal: 1st 6, 2nd 3, 3rd 2.', () => eq([6, 3, 2], place(gGame(3), 2, [3, 2, 1])));
rule('RB', 'Round 4 goal: 1st 7, 2nd 4, 3rd 3.', () => eq([7, 4, 3], place(gGame(3), 3, [3, 2, 1])));
rule('RB', 'Tie for 1st: add the points of the tied places, divide by the tied players, round down; the next place is not awarded (5+2)/2 = 3 in round 2.', () => eq([3, 3, 1], place(gGame(3), 1, [3, 3, 1])));
rule('RB', 'Tie for 1st in round 1: (4+1)/2 = 2 each; the third player gets nothing.', () => eq([2, 2, 0], place(gGame(3), 0, [3, 3, 1])));
rule('RB', 'Three-way tie in round 1: (4+1+0)/3 = 1 each.', () => eq([1, 1, 1], place(gGame(3), 0, [2, 2, 2])));
rule('RB', 'Tie for 2nd: the tied players share places 2 and 3, (2+1)/2 = 1 in round 2.', () => eq([5, 1, 1], place(gGame(3), 1, [4, 2, 2])));
rule('RB', 'A player with none of the targeted item scores nothing, even if that would be a place (only one player has a bird: 2nd place is empty).', () => eq([4, 0, 0], place(gGame(3), 0, [3, 0, 0])));
rule('RB', 'Players with 0 of the item score 0 and do not take a place; a lone scorer in round 2 gets 5.', () => eq([5, 0], place(gGame(2), 1, [1, 0])));
rule('RB', 'Blue side: 1 point per targeted item, maximum 5, in every round.', () => eq([5, 2, 0], place(gGame(3, 'blue'), 0, [7, 2, 0])));
const gc = (gid, build) => { const G = game(); G.goals[0] = gid; build(G); return PP.goalCount(G, 0, gid); };
rule('RB', 'Goal "birds in a habitat" counts the birds in that row.', () => eq(3, gc('birds-G', G => fill(G, 0, 1, 3))));
rule('RB', 'Goal "eggs in a habitat" counts eggs on that row\'s birds only.', () => eq(3, gc('eggs-W', G => { fill(G, 0, 2, 1, { eggs: 3 }); fill(G, 0, 0, 1, { eggs: 2 }); })));
rule('RB', 'Goal "nests with an egg": counts birds of that nest type holding at least 1 egg; star nests count as every type; birds with no egg do not count.', () => { const nest = 'bowl'; eq(2, gc('nest-bowl', G => { put(G, 0, 0, bird(z => z.nest === 'bowl' && z.h === 'F').id, { eggs: 2 }); put(G, 0, 0, bird(z => z.nest === 'star' && z.h.indexOf('F') >= 0).id, { eggs: 1 }); put(G, 0, 0, bird(z => z.nest === 'bowl' && z.h === 'F' && z.id !== D.birds.find(y => y.nest === 'bowl' && y.h === 'F').id).id, { eggs: 0 }); put(G, 0, 1, bird(z => z.nest === 'ground' && z.h === 'G').id, { eggs: 3 }); })); });
rule('RB', 'Goal "sets of eggs": the number of complete sets, one egg in each of the three habitats = the smallest egg count over the rows.', () => eq(1, gc('sets', G => { fill(G, 0, 0, 1, { eggs: 3 }); fill(G, 0, 1, 1, { eggs: 1 }); fill(G, 0, 2, 1, { eggs: 2 }); })));
rule('RB', 'Goal "total birds" counts all birds across the three habitats.', () => eq(4, gc('total', G => { fill(G, 0, 0, 2); fill(G, 0, 1, 1); fill(G, 0, 2, 1); })));

sec('Bonus cards');
const bs = (id, build) => { const G = game(); build(G); G.pl[0].bonus = [id]; return PP.bonusScore(G.pl[0], id); };
rule('APP', 'A tiered bonus card scores its tier points only when the count reaches the tier (4 small birds = 3, 6 = 7, 3 = 0).', () => { const small = D.birds.filter(b => b.ws < 30), r = []; for (const n of [3, 4, 6]) r.push(bs('small-wings', G => { small.slice(0, n).forEach((b, i) => put(G, 0, 'FGW'.indexOf(b.h[0]), b.id)); }).pts); eq([0, 3, 7], r); });
rule('APP', 'A per-bird bonus card scores a fixed amount for each qualifying bird (birds worth 3 points or less, 1 each).', () => eq([2, 2], (() => { const r = bs('bargain', G => { put(G, 0, 0, bird(b => b.p <= 3 && b.h === 'F').id); put(G, 0, 0, bird(b => b.p <= 3 && b.h === 'F' && b.id !== D.birds.find(z => z.p <= 3 && z.h === 'F').id).id); put(G, 0, 0, bird(b => b.p >= 6 && b.h === 'F').id); }); return [r.n, r.pts]; })()));
rule('APP', 'Eating-based bonus cards count birds whose food cost includes that food, wild and either-or slots counted per printed symbol.', () => { const r = bs('seed-saver', G => { put(G, 0, 0, bird(b => b.c.indexOf('seed') >= 0 && b.h === 'F').id); put(G, 0, 0, bird(b => b.c.indexOf('seed') < 0 && b.c.every(c => c.indexOf('seed') < 0) && b.h === 'F').id); }); eq(1, r.n); });
rule('APP', 'Habitat-only bonus cards count birds that live in only that habitat (a two-habitat bird does not count).', () => { const r = bs('woodland', G => { put(G, 0, 0, bird(b => b.h === 'F').id); put(G, 0, 0, bird(b => b.h.length > 1 && b.h.indexOf('F') >= 0).id); }); eq(1, r.n); });
rule('APP', 'Egg-count bonus cards (birds holding 4 or more eggs) count birds with at least that many eggs, 3 points each.', () => { const r = bs('brood', G => { put(G, 0, 0, bird(b => b.e >= 4 && b.h === 'F').id, { eggs: 4 }); put(G, 0, 0, bird(b => b.e >= 4 && b.h === 'F' && b.id !== D.birds.find(z => z.e >= 4 && z.h === 'F').id).id, { eggs: 3 }); }); eq([1, 3], [r.n, r.pts]); });
rule('APP', 'A bonus card is scored only at game end and is included in the final total.', () => { const G = game(); put(G, 0, 0, bird(b => b.p <= 3 && b.h === 'F').id); G.pl[0].bonus = ['bargain']; eq(1, PP.scoreOf(G, 0).bonus); });

sec('Final scoring and ties');
rule('RB', 'Final score = bird points + bonus cards + round goals + 1 per egg + 1 per cached food + 1 per tucked card.', () => { const G = game(); put(G, 0, 0, bird(b => b.p === 4 && b.h === 'F').id, { eggs: 2, cache: 3, tuck: 1 }); G.pl[0].bonus = ['bargain']; G.gres = [{ pts: [4, 0] }, { pts: [2, 0] }]; const s = PP.scoreOf(G, 0); eq([4, 2, 3, 1, 6, 16], [s.birds, s.eggs, s.cache, s.tuck, s.goals, s.total]); });
rule('RB', 'Unused food tokens next to the mat are worth nothing.', () => { const G = game(); G.pl[0].food.grub = 7; eq(0, PP.scoreOf(G, 0).total); });
const endWith = (setup) => { const G = game(); G.round = 3; G._r0 = 3; setup(G); finishRound(G); return G; };
rule('RB', 'The player with the most points wins.', () => { const G = endWith(G => { put(G, 0, 0, bird(b => b.p >= 5 && b.h === 'F').id); }); eq(0, G.winner); });
rule('RB', 'Tie on points: the player with the most unused food tokens wins.', () => { const G = endWith(G => { G.pl[1].food.rodent = 4; }); eq(1, G.winner); });
rule('RB', 'Tie on points and food: the players share the victory.', () => { const G = endWith(G => { }); eq([0, 1], G.winner); });

// =====================================================================================================
if (process.argv.includes('--md')) {
  const L = ['# Perch & Plume: rules checklist (independent of rules-test.js)', '',
    'Every rule of the adapted bird-card engine-builder, numbered. `logic-test.js` has exactly one assertion per number and prints `R<n> expected / got` for each failure. This file is generated: `node logic-test.js --md > RULES-CHECKLIST.md`.', '',
    'Source tags: **RB** official rulebook text (checked 8 Nov 2026), **APP** appendix / designer clarifications of power wording as remembered, **MAT** player-mat artwork as remembered (the rulebook text does not state the row yields, so these three rules are unverified), **HOUSE** this adaptation\'s own choice.', ''];
  let cur = ''; RULES.forEach(r => { if (r.sec !== cur) { cur = r.sec; L.push('', '## ' + cur, ''); } L.push(r.n + '. [' + r.src + '] ' + r.text); });
  L.push('', '## Not testable here (known size differences, see rules-notes.md)', '', '- Roster: the original has 170 birds and 26 bonus cards; this game has 120 original birds and 18 bonus cards, and fewer power types. Goals are 12 tiles.', '- The solo rival is a simplified automa, not the original solo rules.');
  console.log(L.join('\n')); process.exit(0);
}
let pass = 0; const fails = [];
RULES.forEach(r => {
  try { r.fn(); pass++; } catch (e) {
    if (e instanceof Miss) fails.push(r), console.log('FAIL R' + r.n + ' [' + r.sec + '] ' + r.text.slice(0, 90) + '\n   expected ' + JSON.stringify(e.e) + ' got ' + JSON.stringify(e.g));
    else { fails.push(r); console.log('FAIL R' + r.n + ' [' + r.sec + '] ' + r.text.slice(0, 90) + '\n   test/engine error: ' + (e && e.message)); }
  }
});
console.log((fails.length ? 'logic-test: ' : 'PASS logic-test: ') + pass + '/' + RULES.length + ' rules pass' + (fails.length ? ', failing: ' + fails.map(f => 'R' + f.n).join(' ') : ''));
process.exit(fails.length ? 1 : 0);
